vosi:tableset:
{%- for (schema, tables) in table_set.schemas() %}
  {%- let std = hats_query_core::tap::is_tap_schema(schema) %}

    {{ schema }}
    {%- for table in tables %}

      {{ table.name() }}
      {%- for column in table.columns() %}

        {{ column.adql_name() }}
        {%- if let Some(description) = column.description() %}
        {{ description }}
        {%- endif %}
        {%- if let Some(unit) = column.unit() %}
        {{ unit }}
        {%- endif %}
        {%- if let Some(ucd) = column.ucd() %}
        {{ ucd }}
        {%- endif %}
        {%- if let Some(utype) = column.utype() %}
        {{ utype }}
        {%- endif %}
        {{ column.datatype() }}
        {%- if column.indexed() %}
        indexed
        {%- endif %}
        {%- if column.principal() %}
        principal
        {%- endif %}

      {%- endfor %}

    {%- endfor %}

{%- endfor %}
